9	const BASE_PREMIUMS = {
10	  sword: 100,
11	  amulet: 60,
12	  staff: 80,
13	  potion: 40,
14	  rune: 25,
15	  moonstone: 25,
16	} as const satisfies Record<string, number>;
17	
18	type InsurableItemType = keyof typeof BASE_PREMIUMS;
19	
20	type Item = {
21	  type: InsurableItemType;
22	  material?: string;
23	  enchantment?: number;
24	  cursed?: boolean;
25	};
26	
27	type QuoteStep = {
28	  op: "quote";
29	  items: Item[];
30	};
31	
32	type Customer = {
33	  yearsWithMHPCO: number;
34	};
35	
36	type Scenario = {
37	  customer: Customer;
38	  steps: QuoteStep[];
39	};
40	
41	const PROCESSING_FEE = 5;
42	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
43	const CURSE_SURCHARGE_PERCENT = 50;
44	const HIGH_ENCHANTMENT_THRESHOLD = 5;
45	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
46	
47	const percentOf = (amount: number, percent: number): number =>
48	  (amount * percent) / 100;
49	
50	// The MHPCO always rounds in its own favour: premiums (which the customer
51	// pays) go up. Payouts round down, but no test demands that yet.
52	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
53	
54	const itemBasePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
55	
56	// Exactly this many components of the same type form a "building block",
57	// priced as a unit rather than per item.
58	const BUILDING_BLOCK_SIZE = 3;
59	const BUILDING_BLOCK_BASE_PREMIUM = 60;
60	
61	const sumOf = (amounts: number[]): number =>
62	  amounts.reduce((total, amount) => total + amount, 0);
63	
64	const insurableItemTypes = Object.keys(BASE_PREMIUMS) as InsurableItemType[];
65	
66	const alikeItemGroups = (items: Item[]): Item[][] =>
67	  insurableItemTypes
68	    .map((type) => items.filter((item) => item.type === type))
69	    .filter((alikeItems) => alikeItems.length > 0);
70	
71	const formsBuildingBlock = (alikeItems: Item[]): boolean =>
72	  alikeItems.length === BUILDING_BLOCK_SIZE;
73	
74	const alikeGroupBasePremiumOf = (alikeItems: Item[]): number =>
75	  formsBuildingBlock(alikeItems)
76	    ? BUILDING_BLOCK_BASE_PREMIUM
77	    : sumOf(alikeItems.map(itemBasePremiumOf));
78	
79	const policyBasePremiumOf = (items: Item[]): number =>
80	  sumOf(alikeItemGroups(items).map(alikeGroupBasePremiumOf));
81	
82	const isHighlyEnchanted = (item: Item): boolean =>
83	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
84	
85	// Item-specific modifiers apply to the base premium of the affected item.
86	const itemModifiersOf = (item: Item): number => {
87	  const base = itemBasePremiumOf(item);
88	  const curse = item.cursed ? percentOf(base, CURSE_SURCHARGE_PERCENT) : 0;
89	  const enchantment = isHighlyEnchanted(item)
90	    ? percentOf(base, HIGH_ENCHANTMENT_SURCHARGE_PERCENT)
91	    : 0;
92	
93	  return curse + enchantment;
94	};
95	
96	const quote = (step: QuoteStep): QuoteResult => {
97	  const policyBasePremium = policyBasePremiumOf(step.items);
98	  const itemModifiers = sumOf(step.items.map(itemModifiersOf));
99	  const initialAssessmentSurcharge = percentOf(
100	    policyBasePremium,
101	    INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
102	  );
103	
104	  return {
105	    premium: roundedUpInMHPCOsFavour(
106	      policyBasePremium +
107	        itemModifiers +
108	        initialAssessmentSurcharge +
109	        PROCESSING_FEE,
110	    ),
111	  };
112	};
113	
114	export const runScenario = (scenario: Scenario): ScenarioResult => {
115	  return { results: scenario.steps.map(quote) };
116	};
