const isCursed = (item: Item): boolean => item.cursed === true;

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;

// Each surcharge is a percentage of the base premium of the item that
// triggers it. Surcharges are cumulative: every applicable one is added.
type ItemSurcharge = {
  appliesTo: (item: Item) => boolean;
  percent: number;
};

const ITEM_SURCHARGES: ItemSurcharge[] = [
  { appliesTo: isCursed, percent: CURSE_SURCHARGE_PERCENT },
  { appliesTo: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
];

// Item-specific modifiers apply to the base premium of the affected item.
const itemModifiersOf = (item: Item): number =>
  sumOf(
    ITEM_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).map(
      (surcharge) => percentOf(itemBasePremiumOf(item), surcharge.percent),
    ),
  );
